import{_ as t,o,c as e,a5 as s}from"./chunks/framework.Cct9zD0Q.js";const r="/RBQ/nightly/images/software/simulator-architecture.en.svg",i="/RBQ/nightly/images/software/rl-pipeline.en.svg",g=JSON.parse('{"title":"RBQ Simulator","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"software/simulator/overview.md","filePath":"software/simulator/overview.md","lastUpdated":1795599730000}'),n={name:"software/simulator/overview.md"};function l(c,a,d,h,u,m){return o(),e("div",null,[...a[0]||(a[0]=[s('<h1 id="rbq-simulator" tabindex="-1">RBQ Simulator <a class="header-anchor" href="#rbq-simulator" aria-label="Permalink to &quot;RBQ Simulator&quot;">​</a></h1><p>The RBQ open-source package ships several simulators that fall into two groups with <strong>different purposes</strong>:</p><ul><li><strong>Open-source physics simulators</strong> — <a href="/RBQ/nightly/software/simulator/mujoco.html">MuJoCo</a>, <a href="/RBQ/nightly/software/simulator/gazebo.html">Gazebo</a> and <a href="/RBQ/nightly/software/simulator/isaac-sim.html">Isaac Sim</a> run the <strong>full RBQ software stack</strong> against a simulation, so you can develop and test robot software without hardware.</li><li><strong>Reinforcement-learning training environments</strong> — <a href="/RBQ/nightly/software/simulator/rbq-gym.html">Isaac Gym</a> and <a href="/RBQ/nightly/software/simulator/rbq-lab.html">Isaac Lab</a> let you <strong>train a locomotion policy</strong> and <strong>deploy it</strong> to the real robot.</li></ul><h2 id="simulators" tabindex="-1">Simulators <a class="header-anchor" href="#simulators" aria-label="Permalink to &quot;Simulators&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Simulator</th><th>Engine</th><th>Package path</th><th>Purpose</th></tr></thead><tbody><tr><td><strong>MuJoCo</strong></td><td>MuJoCo</td><td><code>rbq_simulator/rbq_mujoco/</code></td><td>Run the full RBQ stack in simulation</td></tr><tr><td><strong>Gazebo</strong></td><td>Ignition Gazebo (Fortress)</td><td><code>rbq_simulator/rbq_gazebo/</code></td><td>Run the full RBQ stack in simulation</td></tr><tr><td><strong>Isaac Sim</strong></td><td>Isaac Sim 5.1</td><td><code>rbq_simulator/rbq_sim/</code></td><td>Run the full RBQ stack in simulation</td></tr><tr><td><strong>Isaac Gym</strong></td><td>IsaacGym (Preview 4)</td><td><code>rbq_simulator/rbq_gym/</code></td><td>RL training — fast parallel training</td></tr><tr><td><strong>Isaac Lab</strong></td><td>Isaac Sim / Isaac Lab</td><td><code>rbq_simulator/rbq_lab/</code></td><td>RL training — high-fidelity simulation</td></tr></tbody></table><p>MuJoCo and Gazebo support two robot variants — the RBQ quadruped (default) and the wheeled RBQ (<code>--wheel</code>, 12 leg joints + 4 driven wheels). Pass the same variant to the RBQ stack with <code>scripts/sim.bash -r wheel</code> so Motion drives the wheels too. Isaac Sim has the quadruped only.</p><p>LiDAR is opt-in in MuJoCo, Gazebo and Isaac Sim, with the same flags — <code>--livox</code> (Livox Mid-360 x2, front / rear) or <code>--ouster</code> (Ouster OS1 x1, rear deck). With no flag the robot carries no LiDAR. MuJoCo&#39;s <code>--ouster</code> draws the housing only.</p><h2 id="how-it-works-mujoco-gazebo-isaac-sim" tabindex="-1">How it works (MuJoCo / Gazebo / Isaac Sim) <a class="header-anchor" href="#how-it-works-mujoco-gazebo-isaac-sim" aria-label="Permalink to &quot;How it works (MuJoCo / Gazebo / Isaac Sim)&quot;">​</a></h2><img src="'+r+'" alt="Simulator and RBQ software stack" style="width:100%;"><ul><li>The simulator and the RBQ software stack run on the same PC and talk over <strong>DDS</strong> (domain 0, loopback). The robot software runs unchanged, as on the real robot.</li><li>The simulator sends the robot&#39;s state (joints, IMU, contacts), camera images and LiDAR clouds; the RBQ software stack sends back its commands to the joints.</li><li>Drive the robot from the web UI (<code>http://127.0.0.1:8080</code>); ROS 2 nodes read the robot&#39;s topics directly.</li></ul><p>Run instructions are on each page: <a href="/RBQ/nightly/software/simulator/mujoco.html#run">MuJoCo</a>, <a href="/RBQ/nightly/software/simulator/gazebo.html#run">Gazebo</a>, <a href="/RBQ/nightly/software/simulator/isaac-sim.html#run">Isaac Sim</a>.</p><h2 id="training-deploying-a-policy-isaac-gym-isaac-lab" tabindex="-1">Training &amp; deploying a policy (Isaac Gym / Isaac Lab) <a class="header-anchor" href="#training-deploying-a-policy-isaac-gym-isaac-lab" aria-label="Permalink to &quot;Training &amp; deploying a policy (Isaac Gym / Isaac Lab)&quot;">​</a></h2><p>The RL environments follow the same <strong>Train → Play → Deploy</strong> pipeline:</p><img src="'+i+`" alt="Train → Play → Sim2Sim → Deploy" style="width:100%;"><p>After training, the <code>policy.onnx</code> and <code>info.json</code> artifacts are loaded by <code>rbq_low_level</code> for on-robot execution.</p><h2 id="repository-structure" tabindex="-1">Repository structure <a class="header-anchor" href="#repository-structure" aria-label="Permalink to &quot;Repository structure&quot;">​</a></h2><p>All simulator code lives under <code>rbq_simulator/</code>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>RBQ/</span></span>
<span class="line"><span>└── rbq_simulator/</span></span>
<span class="line"><span>    ├── rbq_mujoco/        # MuJoCo simulator (full-stack)</span></span>
<span class="line"><span>    ├── rbq_gazebo/        # Ignition Gazebo simulator (full-stack + ROS 2 bridge)</span></span>
<span class="line"><span>    ├── rbq_sim/           # Isaac Sim simulator (full-stack)</span></span>
<span class="line"><span>    ├── rbq_gym/           # Isaac Gym RL environment</span></span>
<span class="line"><span>    └── rbq_lab/           # Isaac Lab RL environment</span></span></code></pre></div><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li><a href="/RBQ/nightly/software/simulator/mujoco.html">MuJoCo →</a> — run the full stack in MuJoCo</li><li><a href="/RBQ/nightly/software/simulator/gazebo.html">Gazebo →</a> — run the full stack in Gazebo</li><li><a href="/RBQ/nightly/software/simulator/isaac-sim.html">Isaac Sim →</a> — run the full stack in Isaac Sim</li><li><a href="/RBQ/nightly/software/simulator/rbq-gym.html">Isaac Gym →</a> — Isaac Gym training guide</li><li><a href="/RBQ/nightly/software/simulator/rbq-lab.html">Isaac Lab →</a> — Isaac Lab training guide</li><li><a href="/RBQ/nightly/software/sdk/cpp/low-level.html">Low Level (RL Policy) →</a> — deploy a trained policy to the real robot</li></ul>`,20)])])}const b=t(n,[["render",l]]);export{g as __pageData,b as default};
